  "subgoals": [
    {
      "id": "G1",
      "objective": "Maximize SWIR-band transmittance for methane absorption feature detection",
      "original_span": "尽可能完整地接收 1000–1700 nm 波段的短波红外信号",
      "operational_definition": "Wavelength integral of the specified optical quantity over the band, divided by band width, for equal-s/p unpolarized light at 0 degrees (execution assumption).",
