        "region": {
          "wavelength_nm": [
            1000,
            1700
          ],
          "angle_deg": 0,
          "polarization": "unpolarized"
        }
      }
    },
    {
      "id": "G2",
      "objective": "Maximize UV/Blue-band reflectance to reduce solar stray light",
      "original_span": "尽可能反射 300–450 nm 波段的近紫外和蓝光杂散辐射",
      "operational_definition": "Wavelength integral of the specified optical quantity over the band, divided by band width, for equal-s/p unpolarized light at 0 degrees (execution assumption).",
