        "objective_id": "G2",
        "metric": "mean_reflectance",
        "sense": "maximize",
        "mean_reduction": "wavelength_integral_mean",
        "region": {
          "wavelength_nm": [
            300,
            450
          ],
          "angle_deg": 0,
          "polarization": "unpolarized"
        }
      }
    }
  ],
  "application_intents": [
    {
      "id": "A1",
      "intent": "Methane leak inspection camera for petrochemical parks and offshore wind farms",
      "original_span": "用于石化园区和海上风电场甲烷泄漏巡检的短波红外成像相机",
      "subgoal_ids": [
        "G1",
        "G2"
      ],
      "operational_definition": null
    },
    {
      "id": "A2",
      "intent": "Improve signal-to-noise ratio of methane absorption features under strong solar background",
      "original_span": "在白天强太阳背景下提高甲烷吸收特征的信噪比",
