    {
      "id": "C1",
      "constraint": "SWIR transmission band: 1000–1700 nm",
      "original_span": "1000–1700 nm"
    },
    {
      "id": "C2",
      "constraint": "UV/Blue reflection band: 300–450 nm",
      "original_span": "300–450 nm"
